H,W=26,24
G=[[6]*W for _ in range(H)]
# Original 3x3 motif, with its anchor at the center.
motif={(-1,-1):1,(-1,0):0,(0,-1):0,(0,0):3,(0,1):0,(1,-1):9}
# Seed motif at center (13,6)
for (dr,dc),v in motif.items(): G[13+dr][6+dc]=v
markers=[(5,12),(8,22),(9,14),(13,15),(14,10),(15,18),(19,7),(22,14),(24,21)]
conflicts=[]
for r,c in markers:
    for (dr,dc),v in motif.items():
        rr,cc=r+dr,c+dc
        if not(0<=rr<H and 0<=cc<W): raise ValueError((rr,cc))
        old=G[rr][cc]
        if old!=6 and old!=v: conflicts.append(((rr,cc),old,v,(r,c)))
        G[rr][cc]=v
print('conflicts',conflicts)
print('dimensions',len(G),len(G[0]))
for row in G: print('['+','.join(map(str,row))+'],')

